def install_pitch_hooks(root: Path) -> list[Path]:
    """Remove the retired pitch-review commit-msg block (Adrian, 2026-10-29: commit runs no hook checks)."""
    removed: list[Path] = []
    pattern = re.compile(re.escape(PITCH_MARKER_START) + r".*?" + re.escape(PITCH_MARKER_END) + r"\n?", re.S)
    for repo in pitch_repos(root):
        hook = _git_hook_path(repo, "commit-msg")
        if not hook.is_file():
            continue
        body = hook.read_text(encoding="utf-8")
        if not pattern.search(body):
            continue
        updated = pattern.sub("", body)
        if updated.strip() in ("", "#!/bin/sh", "#!/bin/sh\nset -eu"):
            hook.unlink()
        else:
            _atomic_write(hook, updated.rstrip() + "\n")
        removed.append(hook)
    return removed


def pitch_hook_errors(root: Path) -> list[str]:
    errors: list[str] = []
    for repo in pitch_repos(root):
        hook = _git_hook_path(repo, "commit-msg")
        if hook.is_file() and PITCH_MARKER_START in hook.read_text(encoding="utf-8"):
            errors.append(f"retired pitch-review commit-msg hook still installed: {repo} (run sync)")
    return errors


