def generate(
    root: Path,
    *,
    mode: str = "generate",
    selected: tuple[Target, ...] | None = None,
) -> list[Path]:
    outputs = all_outputs(root, selected)
    previous = _read_lock(root) if mode == "sync" or selected is not None else {}
    changed: list[Path] = []
    if mode == "sync":
        for path, expected in outputs.items():
            current = path.read_text(encoding="utf-8") if path.is_file() else None
            if current is None or current == expected:
                continue
            relative = path.relative_to(root).as_posix()
            if (
                previous.get(relative) != _content_digest(current)
                and not _clean_in_nested_repository(root, path)
            ):
                raise ValueError(f"generated file was hand-edited: {path}")
    for path, expected in outputs.items():
        current = path.read_text(encoding="utf-8") if path.is_file() else None
        if current == expected:
            continue
        _atomic_write(path, expected)
        changed.append(path)
    lock_path = root / LOCK_REL
    expected_lock = _lock_text(root, outputs, previous if selected is not None else None)
    current_lock = lock_path.read_text(encoding="utf-8") if lock_path.is_file() else None
    if current_lock != expected_lock:
        _atomic_write(lock_path, expected_lock)
        changed.append(lock_path)
    _ensure_host_local_excludes(root)
    return changed


def _line_count(text: str) -> int:
    return len(text.rstrip("\n").splitlines())


def _style_warnings(path: Path, text: str) -> list[str]:
    warnings: list[str] = []
    for number, line in enumerate(text.splitlines(), 1):
        stripped = line.strip()
        if not stripped.startswith("- "):
            continue
        body = stripped[2:]
        if len(body) > 220:
            warnings.append(f"{path}:{number}: long instruction bullet")
        if len(re.findall(r"[.!?](?:\s|$)", body)) > 1:
            warnings.append(f"{path}:{number}: multiple sentences in one bullet")
        if re.search(r"\b(?:is|are|was|were|be|been)\s+\w+(?:ed|en)\b", body, re.I):
            warnings.append(f"{path}:{number}: consider active voice")
def pitch_repos(root: Path) -> list[Path]:
    return [
        root / t.relative
        for t in targets()
        if (root / t.relative / ".git").exists()
        and (root / t.relative / "docs/PITCH.md").is_file()
