def _lock_text(
    root: Path,
    outputs: dict[Path, str],
    preserved: dict[str, str] | None = None,
) -> str:
    digests = dict(preserved or {})
    digests.update({
        path.relative_to(root).as_posix(): _content_digest(text)
        for path, text in outputs.items()
    })
    payload = {
        "schema": 1,
        "generated_by": "tools/agent-rules/manage.py",
        "outputs": dict(sorted(digests.items())),
    }
    return json.dumps(payload, indent=2, sort_keys=True) + "\n"


