def _clean_in_nested_repository(root: Path, path: Path) -> bool:
    """A committed generated copy is stale, not an uncommitted hand edit."""
    for target in targets():
        repository = root / target.relative
        # The workspace root is not a nested repository: its generated files
        # keep the strict hand-edit check.
        if repository.resolve() == root.resolve():
            continue
        try:
            relative = path.relative_to(repository)
        except ValueError:
            continue
        if not (repository / ".git").exists():
            return False
        result = subprocess.run(
            ["git", "status", "--porcelain=v1", "--", relative.as_posix()],
            cwd=repository,
            capture_output=True,
            text=True,
            check=False,
        )
        return result.returncode == 0 and not result.stdout.strip()
    return False
